SELECT int64 = float32 AS c0, toTypeName(int64 = float32) AS t0, int64 != float32 AS c1, toTypeName(int64 != float32) AS t1, int64 < float32 AS c2, toTypeName(int64 < float32) AS t2, int64 <= float32 AS c3, toTypeName(int64 <= float32) AS t3, int64 > float32 AS c4, toTypeName(int64 > float32) AS t4, int64 >= float32 AS c5, toTypeName(int64 >= float32) AS t5 FROM he24.numeric ORDER BY row_id
